#!/bin/bash
# .agents/verify.sh: the fast gate the ai-native-kit Stop hook runs before an agent may finish
# (Claude Code and Codex). It runs only the checks for the parts of the repo that changed.
# Generated by project_gate.py on 2026-10-13; edit freely, keep the step lines inside the block.
#   VERIFY_FULL=1 .agents/verify.sh   run every check, including slow ones
#   python3 ~/.agents/ai-native-kit/tools/project_gate.py baseline           re-record which checks already fail (known_red), which could
#                                     not run because a tool or dependency is missing (needs_setup), and which are slow
# Exit 0 = pass. Any other exit = the agent is sent back with this output.
set -uo pipefail
BASELINE_PENDING=0
BASELINE_DATE=2026-10-13
ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || exit 0
cd "$ROOT" || exit 1
export CI=1
MODE=fast
[ "${VERIFY_FULL:-0}" = 1 ] && MODE=full
[ "${VERIFY_BASELINE:-0}" = 1 ] && MODE=baseline

if [ "$MODE" = fast ] && [ "$BASELINE_PENDING" = 1 ]; then
  echo "verify: baseline not recorded yet, so the gate passes. Record it with: python3 ~/.agents/ai-native-kit/tools/project_gate.py baseline"
  exit 0
fi

# -z and core.quotePath=false: paths with spaces or accents stay literal, so area patterns match them.
CHANGED=$(git -c core.quotePath=false --no-optional-locks status --porcelain -z --no-renames --untracked-files=all | tr '\0' '\n' | cut -c4-)
if [ "$MODE" = fast ] && [ -z "$CHANGED" ]; then echo "verify: nothing changed"; exit 0; fi
# A here-string, not a pipe: with pipefail, grep -q closing a pipe early would read as "no match".
want() { [ "$MODE" != fast ] || grep -Eq -- "$1" <<< "$CHANGED"; }

with_timeout() {
  # with_timeout <seconds> <command...>: at the limit, stop the whole process group; exit 142
  perl -e '
    my $t = shift @ARGV;
    my $pid = fork();
    exit 127 unless defined $pid;
    if ($pid == 0) {
      setpgrp(0, 0); exec { $ARGV[0] } @ARGV;
      my $missing = $!{ENOENT}; my $why = "$!";
      print STDERR $missing ? "$ARGV[0]: command not found\n" : "$ARGV[0]: $why\n";
      exit($missing ? 127 : 126);
    }
    local $SIG{ALRM} = sub { kill "TERM", -$pid; sleep 2; kill "KILL", -$pid; exit 142; };
    alarm $t;
    waitpid($pid, 0);
    my $s = $?;
    exit(($s & 127) ? 128 + ($s & 127) : $s >> 8);
  ' "$@"
}

py_syntax() {
  # compile every .py file in memory (no .pyc written) and report syntax errors
  python3 - <<'PY'
import os, sys
bad = 0
for dp, dn, fn in os.walk("."):
    dn[:] = [d for d in dn if d not in {".git", ".venv", "venv", "env", ".tox", "node_modules", "build", "dist", "__pycache__", "site-packages"}
             and not os.path.exists(os.path.join(dp, d, "pyvenv.cfg"))]
    for f in fn:
        if f.endswith(".py"):
            p = os.path.join(dp, f)
            try:
                with open(p, "rb") as fh:
                    compile(fh.read(), p, "exec")
            except SyntaxError as e:
                print("{}:{}: {}".format(p, e.lineno, e.msg))
                bad = 1
            except (ValueError, OSError):
                pass
sys.exit(bad)
PY
}

FAILED=0
step() {
  # step <label> <dir> <command...>
  label=$1; dir=$2; shift 2
  if [ "$MODE" = baseline ]; then
    start=$(date +%s)
    log="$ROOT/.scratch/gate-baseline/$(printf '%s' "$label" | LC_ALL=C tr -c 'A-Za-z0-9._-' '_').log"
    mkdir -p "$ROOT/.scratch/gate-baseline"
    if [ "$(type -t "$1")" = function ]; then
      (cd "$dir" && "$@") >"$log" 2>&1 </dev/null
    else
      (cd "$dir" && with_timeout "${VERIFY_STEP_TIMEOUT:-300}" "$@") >"$log" 2>&1 </dev/null
    fi
    rc=$?
    printf '@@gate\t%s\t%s\t%s\n' "$label" "$rc" "$(( $(date +%s) - start ))"
    return 0
  fi
  printf '\n== %s\n' "$label"
  if ! (cd "$dir" && "$@" </dev/null) 2>&1 | tail -40; then FAILED=1; fi
}
known_red() {
  if [ "$MODE" = baseline ]; then step "$@"; return 0; fi
  printf '\n== %s: skipped, it already failed when the baseline was recorded (%s; log in .scratch/gate-baseline/). Fix it, then run the baseline again.\n' "$1" "$BASELINE_DATE"
}
needs_setup() {
  if [ "$MODE" = baseline ]; then step "$@"; return 0; fi
  printf '\n== %s: NOT CHECKED, a tool or dependency was missing when the baseline was recorded (%s; log in .scratch/gate-baseline/). Install it (AGENTS.md lists the commands), then run the baseline again.\n' "$1" "$BASELINE_DATE"
  printf '@@needs_setup\t%s\n' "$1"
}
slow() {
  if [ "$MODE" != fast ]; then step "$@"; return 0; fi
  printf '\n== %s: skipped in the fast gate (slow); runs with VERIFY_FULL=1.\n' "$1"
}

# >>> project_gate checks (verbs: step | known_red | slow; `project_gate.py baseline` rewrites them)
# No checks detected. Add step lines, for example:
# if want "."; then step "root: test" . make test; fi
# <<< project_gate checks

[ "$MODE" = baseline ] && exit 0
if [ "$FAILED" -ne 0 ]; then
  printf '\nverify: FAILED. Fix the errors above (do not weaken tests or checks), then stop again.\n'
  exit 1
fi
printf '\nverify: passed for the changed areas.\n'
